args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-11-05-kras-logo');S<-file.path(P,'biofigure');.libPaths(c(file.path(P,'work/2026-10-28-sequence-figures/Rlib'),.libPaths()));library(ggplot2);library(ggseqlogo);library(cowplot);cowplot::set_null_device('agg');library(grid);z<-readRDS(file.path(W,'prepared-data.rds'));ragg::agg_png(file.path(W,'layout-device.png'),width=183,height=127,units='mm',res=150)
